+
+			_, err := server.CreateToken(ctx, &auth.CreateTokenRequest{Name: "test"})
+			require.NoError(t, err)
+			span.End()
+
+			events := recorder.Ended()[0].Events()
+			if !enabled {
+				require.Empty(t, events)
+				return
+			}
+			require.Len(t, events, 1)
